import { api, tags } from '@igblsln/store';
export const boqApi = api.injectEndpoints({
    overrideExisting: false,
    endpoints: (build) => ({
        getBoqByProject: build.query({
            query: (projectId) => ({
                url: `boq/${projectId}`,
            }),
            providesTags: (_result, _err, projectId) => [{ type: tags.BOQ_BY_PROJECT, id: projectId }],
        }),
        getBoqSummary: build.query({
            query: (projectId) => ({
                url: `boq/summary/${projectId}`,
            }),
            providesTags: (_result, _err, projectId) => [{ type: tags.BOQ_SUMMARY, id: projectId }],
        }),
        generateBoq: build.mutation({
            query: ({ projectId, payload }) => ({
                url: `boq/generate/${projectId}`,
                method: 'POST',
                body: payload,
            }),
            invalidatesTags: (_result, _err, { projectId }) => [{ type: tags.BOQ_BY_PROJECT, id: projectId }],
        }),
    }),
});
export const { useGetBoqByProjectQuery, useGetBoqSummaryQuery, useGenerateBoqMutation, } = boqApi;
